  'use strict';

  function actionLabel(a) {
    return ({ 'skip': '跳过', 'reply-rule': '规则回复', 'llm': 'LLM 处理' })[a] || a;
  }

  function skillSourceLabel(s) {
    return ({ 'explicit': '显式', 'intent': '意图', 'keyword': '关键词' })[s] || s;
  }

