function _fmtNum(n) {
    n = Number(n) || 0;
    if (n >= 100000000) return (n / 100000000).toFixed(1).replace(/\.0$/, '') + '亿';
    if (n >= 10000) return (n / 10000).toFixed(1).replace(/\.0$/, '') + '万';
    return String(n);
}
function _platformLabel(p) {
    const map = { dingtalk: '钉钉', feishu: '飞书', wecom: '企微', all: '通用' };
    return map[p] || p;
}

