let _cqPolling = null;

// 百分比格式化
function cqFmtPct(v) {
    if (v == null || v === 0) return "0%";
    return (v * 100).toFixed(1) + "%";
}

// ¥ 成本格式化（CNY）
function cqFmtCostCny(cny) {
    if (cny == null || cny === 0) return "¥0.00";
    if (cny < 0.01) return "¥" + cny.toFixed(4);
    return "¥" + cny.toFixed(2);
}

